from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    latest = {}

    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            event_id = ('id', event['id'])
            revision = event.get('revision', 0)
        else:
            event_id = ('anonymous', position)
            revision = 0

        previous = latest.get(event_id)
        if previous is None or revision >= previous[0]:
            latest[event_id] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    for _, _, event in latest.values():
        if event.get('void') is True:
            continue

        account = event.get('account') or 'default'
        currency = event.get('currency') or 'USD'
        key = f'{account}|{currency}'
        value = amount(event, data['rounding'])
        if event.get('kind') == 'refund':
            value = -value
        balances[key] = balances.get(key, 0) + value

    if not balances:
        balances['default|USD'] = 0
    return {'balances': balances}
